import{_ as e,l,o as r,b as i,q as d,d as S,f as t,m as n}from"./chunks/framework.Tf23FRXt.js";const g=JSON.parse('{"title":"苏醒遗迹喀恩埋没圣堂","description":"","frontmatter":{},"headers":[{"level":2,"title":"进场 ~ BOSS 1","slug":"进场-boss-1","link":"#进场-boss-1","children":[]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[{"level":3,"title":"BOSS 2 仙人刺女皇","slug":"boss-2-仙人刺女皇","link":"#boss-2-仙人刺女皇","children":[]}]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[{"level":3,"title":"BOSS 3 审理神代言者","slug":"boss-3-审理神代言者","link":"#boss-3-审理神代言者","children":[]}]}],"relativePath":"duty/26.htm.md","filePath":"duty/26.md","lastUpdated":1791101830000}'),b={name:"duty/26.htm.md"};function B(O,s,a,p,m,u){const o=l("Role");return r(),i("div",null,[s[11]||(s[11]=d('<h1 id="苏醒遗迹喀恩埋没圣堂" tabindex="-1">苏醒遗迹喀恩埋没圣堂</h1><p>继承低级圣堂的麻烦，一脉相承。</p><h2 id="进场-boss-1" tabindex="-1">进场～BOSS 1</h2><p>捡完第一个石头之后，有能力一波的人会 T 拉住怪，治疗开门，把所有怪放在门里的地刺上 (人不要站上去)，地刺会对怪造成伤害并带来易伤效果，好顶赞。</p><p>BOSS 1 <strong>受损的审判化身</strong>，开战后不久，会有某个部位发光，集火该部位即可，如果有人看到也可以标个号方便新人输出。被点名的人建议远离人群，会放一个石球并持续 AOE。地面出现流沙要及时走出去，陷到底就挂了。</p><h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>打完老一之后出门紧紧贴着左墙走是不会引怪的（走到头要远绕一点点再下来)，<strong>代言者的爪子</strong>会抓人，记得先打。途中的<strong>蛇</strong>会石化，也要优先集火 (建议标号)。</p><h3 id="boss-2-仙人刺女皇" tabindex="-1">BOSS 2 仙人刺女皇</h3><p>满地仙人掌场面将会十分混乱，记得焦点<strong>仙人刺女皇</strong>并标号。BOSS 读条<mark>十万针刺</mark>时，需要集火攻击打断咏唱，咏唱完成则强制团灭。场上出现<strong>仙人掌守卫</strong>时 (会同时有一个巨大的保护特效)，将无法攻击 BOSS，但 BOSS 同时在读条十万针刺，需要先打掉守卫，再来攻击 BOSS，根据 DPS 决定是否需要放 LB。只要打掉 BOSS，其他小怪都会消失，如果 T 奶没有压力的话，可以不用管其他小怪 (但场地可能难以落脚…)。</p><h2 id="boss-2-boss-3" tabindex="-1">BOSS 2 ~ BOSS 3</h2><p>一路没啥要注意的，最后一波小怪打完之后，左右里侧各有一个机关，两个机关都打开后，再开中间的机关就可以了。</p><h3 id="boss-3-审理神代言者" tabindex="-1">BOSS 3 审理神代言者</h3>',12)),S("p",null,[s[0]||(s[0]=t("开场",-1)),n(o,{name:"tank"}),s[1]||(s[1]=t("T 把",-1)),s[2]||(s[2]=S("strong",null,"审理神代言者",-1)),s[3]||(s[3]=t("放在中场，并观察场地四周，四周会升起棺材，里面会跑出木乃伊… 躲开它的直线前进方向，否则会被上 buff。BOSS 读条",-1)),s[4]||(s[4]=S("mark",null,"怨恨的斩击",-1)),s[5]||(s[5]=t("，是对随机一名玩家的直线范围 AOE，看到此技能请躲开 BOSS 正面面向。BOSS 还会随机连线一名玩家，被连线的人需要绕场狂跑 (…)，有眩晕的",-1)),n(o,{name:"tank"}),s[6]||(s[6]=t("T 或",-1)),n(o,{name:"dps"}),s[7]||(s[7]=t("近战 DPS 可以眩晕 BOSS（注意",-1)),s[8]||(s[8]=S("a",{href:"/basic/battle-mech.htm"},"眩晕衰减",-1)),s[9]||(s[9]=t("），BOSS 抓到被连线的人就会不断给他上 buff…buff 叠到 4 层的玩家会被关小黑屋，然后变成木乃伊斜穿场地，被扫到的其他玩家也会被叠 buff。尤其",-1)),n(o,{name:"tank"}),s[10]||(s[10]=t("T 被关小黑屋的话，BOSS 就会转身攻击二仇玩家，需要格外注意。",-1))])])}const k=e(b,[["render",B]]);export{g as __pageData,k as default};
